import sqlite3

from flask import current_app, g


def get_db():
    if "sqlite" not in g:
        g.sqlite = sqlite3.connect(current_app.config["CATALOG_DATABASE"], detect_types=sqlite3.PARSE_DECLTYPES)
        g.sqlite.row_factory = sqlite3.Row
    return g.sqlite


def close_db(_exc=None):
    conn = g.pop("sqlite", None)
    if conn is not None:
        conn.close()

